router.get('/orders/:id', async (req, res, next) => {
  try {
    const order = await orders.find(req.params.id);   // worker services the request
    res.render('orders/show', { order });             // dispatcher selects + renders the view
  } catch (err) {
    next(err);                                        // error view chosen centrally
  }
});
